@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#f8f2e7;--muted:rgba(248,242,231,.67);--gold:#e5b969;--green:#18251e;--panel:rgba(25,34,28,.84);--line:rgba(246,234,211,.16)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#7d9a74;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#829b75}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(16,25,20,.48) 0%,transparent 21%,transparent 66%,rgba(16,25,20,.32) 100%),radial-gradient(ellipse at 50% 45%,transparent 45%,rgba(19,31,24,.24) 100%)}
.topbar{position:absolute;top:0;left:0;right:0;height:72px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(20,29,23,.68),rgba(20,29,23,.05));z-index:3}.brand{display:flex;align-items:center;gap:11px;color:#fff4db;text-decoration:none;font-size:12px;letter-spacing:2px;font-weight:700}.brand i{font-family:'Playfair Display';font-weight:600;color:var(--gold);font-size:15px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid rgba(230,189,111,.72);border-radius:50%;font-size:14px;color:var(--gold)}.day-pill{position:absolute;left:50%;transform:translateX(-50%);height:34px;padding:0 13px;display:flex;gap:9px;align-items:center;border:1px solid rgba(255,255,255,.23);border-radius:20px;background:rgba(28,38,31,.45);font-size:10px;letter-spacing:.8px;color:rgba(255,248,230,.86)}.day-pill b{color:#fff}.sun-icon{font-size:13px;color:var(--gold)}.pill-divider{height:13px;width:1px;background:rgba(255,255,255,.23)}#clock{font-variant-numeric:tabular-nums}.top-right{display:flex;gap:10px;align-items:center}.season{font-size:9px;letter-spacing:1.55px;color:rgba(249,242,225,.72);margin-right:8px}.icon-button{width:29px;height:29px;border:1px solid rgba(255,255,255,.28);background:rgba(25,34,28,.28);border-radius:50%;font-size:14px;cursor:pointer}.icon-button:hover,.camera-button:hover{background:rgba(255,255,255,.18)}
.quest-card{position:absolute;top:99px;left:40px;width:257px;padding:18px 19px 15px;border:1px solid rgba(245,233,210,.16);border-radius:5px;background:var(--panel);box-shadow:0 9px 28px rgba(13,23,17,.14);backdrop-filter:blur(12px);z-index:2}.quest-eyebrow,.inventory-title{font-size:9px;font-weight:700;letter-spacing:1.35px;color:#dfbb78}.quest-dot{display:inline-block;width:6px;height:6px;margin:0 5px 1px 0;border-radius:50%;background:#dfbb78;box-shadow:0 0 9px #dfbb78}.quest-card h1{font:700 22px 'Playfair Display',serif;letter-spacing:-.3px;margin:10px 0 5px}.quest-card>p{font-size:11px;line-height:1.55;color:var(--muted);margin:0 0 15px}.quest-progress{display:flex;align-items:center;justify-content:space-between;font-size:9px;color:rgba(255,248,231,.7);gap:10px}.progress-track{height:4px;width:72px;background:rgba(255,255,255,.15);border-radius:6px;overflow:hidden}.progress-track i{height:100%;display:block;width:0;background:#e2b764;transition:width .3s}.quest-reward{padding-top:12px;margin-top:12px;border-top:1px solid rgba(255,255,255,.1);font-size:9px;color:rgba(255,248,231,.65)}.coin,.heart-small{color:var(--gold);font-size:10px}.heart-small{color:#dc9278}.quest-reward b{color:#fff1d4;font-weight:600}.reward-separator{margin:0 5px;color:rgba(255,255,255,.3)}
.location{position:absolute;top:100px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;text-align:left;color:#fff7e7;text-shadow:0 1px 5px rgba(20,31,23,.65);z-index:2}.location-pin{font-size:18px;color:#f0d093}.location b,.location small{display:block}.location b{font-size:10px;letter-spacing:1.8px}.location small{font-size:8px;letter-spacing:1.25px;color:rgba(255,246,225,.73);margin-top:3px}.weather{position:absolute;top:103px;right:42px;display:flex;gap:8px;align-items:center;font-size:10px;color:rgba(255,249,230,.84);text-shadow:0 1px 5px #34402d}.weather>span:first-child{color:#f3cd76;font-size:14px}.weather i{height:13px;width:1px;background:rgba(255,255,255,.4);margin:0 2px}
.inventory{position:absolute;left:40px;bottom:30px;width:258px;padding:13px 15px 14px;border:1px solid rgba(245,233,210,.17);border-radius:5px;background:var(--panel);backdrop-filter:blur(12px);z-index:2}.inventory-title{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.3px}.inventory-title span{color:rgba(255,246,224,.55);font-weight:500;letter-spacing:.5px}.inventory-items{display:flex;gap:7px;margin-top:10px}.item-slot{width:34px;height:34px;border:1px solid rgba(242,231,207,.18);background:rgba(255,255,255,.04);border-radius:3px;display:grid;place-items:center;color:#e5c68b;font-size:17px;position:relative;animation:pop .25s ease-out}.item-slot small{position:absolute;right:3px;bottom:0;font-size:7px;color:rgba(255,255,255,.65)}@keyframes pop{from{transform:scale(.6);opacity:0}to{transform:scale(1);opacity:1}}
.interaction-controls{position:absolute;bottom:34px;right:39px;display:flex;gap:17px;align-items:center;z-index:2}.desktop-help{font-size:10px;color:rgba(255,247,226,.78);text-shadow:0 1px 5px #18251e}.desktop-help kbd{font-family:inherit;font-size:9px;color:#fff3d8;display:inline-grid;place-items:center;min-width:19px;height:19px;margin:0 3px;padding:0 4px;border:1px solid rgba(255,244,218,.36);border-radius:3px;background:rgba(25,35,28,.4)}.control-divider{margin:0 8px;color:rgba(255,255,255,.45)}.camera-button{height:34px;padding:0 12px;border:1px solid rgba(255,255,255,.25);border-radius:3px;background:rgba(25,34,28,.55);font-size:9px;letter-spacing:1px;cursor:pointer}.camera-button span{font-size:13px;margin-right:6px;color:#ead19d}.interact-hint{position:absolute;left:50%;top:61%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;padding:9px 12px;border:1px solid rgba(255,244,218,.28);border-radius:4px;background:rgba(24,33,27,.83);box-shadow:0 4px 18px rgba(20,30,22,.24);font-size:11px;opacity:0;transition:opacity .2s;pointer-events:none;z-index:3;white-space:nowrap}.interact-hint.show{opacity:1}.keycap{display:grid;place-items:center;width:21px;height:21px;border-radius:3px;background:#e9c77f;color:#293128;font-weight:700}.hint-arrow{color:#e9c77f;margin-left:4px}.crosshair{position:absolute;left:50%;top:50%;width:21px;height:21px;transform:translate(-50%,-50%);opacity:.5;pointer-events:none;z-index:1}.crosshair:before,.crosshair:after,.crosshair span:before,.crosshair span:after{content:'';position:absolute;background:rgba(255,248,230,.83);box-shadow:0 1px 3px #34402d}.crosshair:before{width:1px;height:5px;left:10px;top:0}.crosshair:after{width:1px;height:5px;left:10px;bottom:0}.crosshair span:before{height:1px;width:5px;left:0;top:10px}.crosshair span:after{height:1px;width:5px;right:0;top:10px}
.modal-backdrop{position:absolute;inset:0;z-index:10;display:grid;place-items:center;background:rgba(17,26,20,.44);backdrop-filter:blur(3px);transition:opacity .35s}.modal-backdrop.hidden{opacity:0;pointer-events:none}.modal{position:relative;width:min(410px,calc(100vw - 34px));padding:33px 39px 24px;text-align:center;border:1px solid rgba(236,212,166,.4);border-radius:5px;background:linear-gradient(145deg,rgba(36,47,38,.96),rgba(26,37,29,.97));box-shadow:0 18px 65px rgba(12,21,15,.4)}.modal-close{position:absolute;right:14px;top:10px;background:none;border:0;color:rgba(255,245,226,.55);font-size:24px;cursor:pointer}.modal-sun{font-size:25px;color:var(--gold);line-height:1}.modal-kicker{font-size:8px;letter-spacing:2px;color:#d9bd86;margin-top:11px}.modal h2{font:700 34px/1.1 'Playfair Display',serif;margin:13px 0}.modal h2 em{font-weight:600;color:#e5c27e}.modal>p{font-size:11px;line-height:1.7;color:rgba(248,242,231,.72);max-width:295px;margin:0 auto 18px}.modal-tip{display:flex;text-align:left;gap:10px;padding:11px 12px;border:1px solid rgba(233,203,149,.21);border-radius:3px;background:rgba(238,207,151,.055);margin:0 0 17px}.modal-tip>span{color:#e8c67f;font-size:14px}.modal-tip p{font-size:9px;line-height:1.55;margin:0;color:rgba(248,242,231,.7)}.modal-tip b{font-size:10px;color:#fff0d3}.primary-button{width:100%;height:42px;border:0;border-radius:3px;background:#dfb767;color:#2c3024;font-size:9px;font-weight:700;letter-spacing:1.15px;cursor:pointer;transition:background .2s,transform .2s}.primary-button:hover{background:#efca81;transform:translateY(-1px)}.primary-button span{font-size:15px;margin-left:8px}.modal-foot{margin-top:16px;font-size:7px;letter-spacing:2px;color:rgba(242,229,201,.42)}
.toast{position:absolute;left:50%;top:76px;transform:translate(-50%,-12px);z-index:5;padding:9px 16px;border:1px solid rgba(241,218,173,.26);border-radius:3px;background:rgba(26,37,30,.9);font-size:11px;color:#fff0d3;opacity:0;transition:all .25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-action{display:none}.mobile-controls{display:none}.completion-banner{position:absolute;z-index:6;left:50%;top:21%;transform:translate(-50%,-12px);display:flex;align-items:center;gap:12px;padding:13px 17px;background:rgba(27,39,30,.94);border:1px solid rgba(239,208,148,.45);border-radius:4px;box-shadow:0 8px 26px #24332855;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.completion-banner.show{opacity:1;transform:translate(-50%,0)}.banner-star{color:#e7c37d;font-size:19px}.completion-banner b,.completion-banner small{display:block}.completion-banner b{font:600 14px 'Playfair Display',serif}.completion-banner small{font-size:9px;color:var(--muted);margin-top:3px}.banner-reward{font-size:10px;color:#e7c37d;margin-left:12px}.fade-overlay{position:absolute;inset:0;z-index:8;background:#18251e;opacity:0;pointer-events:none;transition:opacity .3s}.fade-overlay.show{opacity:1}.mobile-controls,.touch-action{z-index:4}
@media(max-width:700px){.topbar{height:58px;padding:0 16px}.brand{font-size:9px;letter-spacing:1.3px;gap:7px}.brand-mark{width:23px;height:23px;font-size:12px}.day-pill{top:64px;left:auto;right:15px;transform:none;height:29px;font-size:9px;padding:0 10px}.top-right{gap:7px}.season{display:none}.icon-button{width:27px;height:27px}.quest-card{top:68px;left:14px;width:min(221px,60vw);padding:12px 13px 11px}.quest-eyebrow{font-size:8px}.quest-card h1{font-size:18px;margin:7px 0 3px}.quest-card>p{font-size:9px;line-height:1.4;margin-bottom:9px}.quest-progress{font-size:8px}.quest-reward{font-size:8px;padding-top:8px;margin-top:8px}.progress-track{width:50px}.location{top:calc(58px + 18px);left:50%;gap:6px}.location b{font-size:8px}.location small{font-size:7px}.location-pin{font-size:15px}.weather{top:auto;bottom:174px;right:16px;font-size:9px;gap:5px}.inventory{left:14px;bottom:14px;width:196px;padding:10px 11px}.inventory-items{gap:5px;margin-top:7px}.item-slot{width:29px;height:29px;font-size:15px}.inventory-title{font-size:7px}.interaction-controls{right:13px;bottom:18px;gap:0}.desktop-help{display:none}.camera-button{height:32px;padding:0 9px;font-size:8px}.mobile-controls{display:block;position:absolute;bottom:64px;left:22px;width:112px;height:112px}.joystick-base{width:92px;height:92px;margin:0 auto;border-radius:50%;border:1px solid rgba(255,245,218,.31);background:rgba(30,42,33,.26);backdrop-filter:blur(5px);touch-action:none;position:relative}.joystick-base:before{content:'';position:absolute;inset:15px;border:1px solid rgba(255,245,218,.12);border-radius:50%}.joystick-knob{position:absolute;left:50%;top:50%;width:37px;height:37px;border:1px solid rgba(255,245,218,.55);border-radius:50%;background:rgba(225,196,137,.32);transform:translate(-50%,-50%)}.move-label{display:block;margin-top:6px;text-align:center;font-size:7px;letter-spacing:1.6px;color:rgba(255,247,226,.72)}.touch-action{position:absolute;display:block;right:20px;bottom:69px;width:66px;height:66px;border-radius:50%;border:1px solid rgba(241,216,169,.62);background:rgba(32,45,34,.68);color:#f4d493;font-size:9px;font-weight:700;line-height:1.25;letter-spacing:.5px;box-shadow:0 3px 14px #18251e44}.touch-action span{font-size:6px;letter-spacing:.5px}.crosshair{display:none}.interact-hint{top:57%;font-size:9px;padding:7px 10px}.keycap{width:19px;height:19px}.weather{bottom:171px}.modal{padding:27px 25px 20px;width:min(360px,calc(100vw - 30px))}.modal h2{font-size:30px}.modal>p{font-size:10px}.modal-tip{padding:9px}.modal-tip p{font-size:8px}.primary-button{height:39px}.modal-foot{margin-top:12px}.completion-banner{top:31%}}
@media(max-height:620px) and (min-width:701px){.quest-card{top:82px;padding:12px 15px}.quest-card h1{margin:7px 0 3px}.quest-card>p{margin-bottom:9px}.quest-reward{padding-top:8px;margin-top:8px}.location,.weather{top:86px}.modal{padding-top:22px;padding-bottom:17px}.modal h2{font-size:29px;margin:9px 0}.modal>p{margin-bottom:12px}}
@media (prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9cad83);
scene.fog = new THREE.Fog(0x9cad83, 25, 82);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
const camera = new THREE.PerspectiveCamera(54, 1, .1, 120);
const hemi = new THREE.HemisphereLight(0xffefd7, 0x4c6341, 2.0); scene.add(hemi);
const sun = new THREE.DirectionalLight(0xffe6ae, 3.1); sun.position.set(-14, 25, 12); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -28; sun.shadow.camera.right = 28; sun.shadow.camera.top = 28; sun.shadow.camera.bottom = -28; sun.shadow.bias = -0.0004; scene.add(sun);
const fill = new THREE.DirectionalLight(0xd0dfef, .7); fill.position.set(13, 9, -15); scene.add(fill);
const mats = {};
const mat = (name, color, roughness=1) => mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness });
const groundMat = mat('ground', 0x81966a), pathMat=mat('path',0xc5ac7f), pathLight=mat('pathLight',0xd1bb92), wood=mat('wood',0x76513a), darkWood=mat('darkWood',0x513a2b), plaster=mat('plaster',0xd9c7a2), plasterRose=mat('rose',0xc8a28a), roof=mat('roof',0x65463a), roofLight=mat('roofLight',0x805642), stone=mat('stone',0x88816c), leaf=mat('leaf',0x58764b), leafLight=mat('leafLight',0x718c54), herbMat=mat('herb',0x97b65c), flowerMat=mat('flower',0xd9bc78), cloth=mat('cloth',0x8c5142), blueCloth=mat('blueCloth',0x586b72), skin=mat('skin',0xd4a37c), iron=mat('iron',0x554f43), gold=mat('gold',0xd7b261);
function box(parent, x,y,z, sx,sy,sz, material, cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}
function sphere(parent,x,y,z,sx,sy,sz,material,detail=1){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(1,detail),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
const world = new THREE.Group(); scene.add(world);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(130,130),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.08;ground.receiveShadow=true;world.add(ground);
// Soft rolling meadow mounds around the village edge
for(let i=0;i<15;i++){const a=i/15*Math.PI*2, r=28+(i%3)*3;const hill=sphere(world,Math.cos(a)*r,-2.5,Math.sin(a)*r,9,3.8,8, i%2?mat('hillA',0x738a61):mat('hillB',0x89986d),2);}
// Winding, pale packed-earth lanes
function path(points,width){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,.015,z)));const verts=[],indices=[];const steps=100;for(let i=0;i<=steps;i++){const t=i/steps,p=curve.getPoint(t),tan=curve.getTangent(t),side=new THREE.Vector3(-tan.z,0,tan.x).normalize();verts.push(p.x+side.x*width/2,.016,p.z+side.z*width/2,p.x-side.x*width/2,.016,p.z-side.z*width/2);if(i<steps){const n=i*2;indices.push(n,n+1,n+2,n+1,n+3,n+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();const mesh=new THREE.Mesh(g,pathMat);mesh.receiveShadow=true;world.add(mesh);}
path([[-23,1],[-12,0],[-7,-1],[0,0],[7,2],[14,2],[24,1]],3.4);path([[0,-24],[-1,-14],[0,-8],[0,0],[1,8],[0,14],[1,23]],3.2);path([[-11,13],[-9,9],[-8,4],[-7,0]],2.2);path([[11,-10],[8,-6],[5,-2],[0,0]],2);
// Village buildings: cozy timber-frame cottages with steep gabled roofs.
function cottage(x,z,scale=1,wall=plaster,roofMat=roof,rotation=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rotation;g.scale.setScalar(scale);world.add(g);
 box(g,0,1.3,0,4.1,2.6,3.3,wall); // half-timbering
 for(const y of [.35,1.15,2.25])box(g,0,y,1.68,4.2,.12,.1,darkWood);
 for(const x2 of [-1.92,0,1.92])box(g,x2,1.3,1.68,.13,2.3,.12,darkWood);
 // two roof planes and end gable
 const left=new THREE.Mesh(new THREE.BoxGeometry(2.48,.2,3.75),roofMat);left.position.set(-.62,3.06,0);left.rotation.z=-.61;left.castShadow=true;g.add(left);
 const right=new THREE.Mesh(new THREE.BoxGeometry(2.48,.2,3.75),roofMat);right.position.set(.62,3.06,0);right.rotation.z=.61;right.castShadow=true;g.add(right);
 const end=new THREE.Mesh(new THREE.ConeGeometry(2.06,1.65,4),wall);end.rotation.y=Math.PI/4;end.position.set(0,2.54,-1.69);end.scale.set(1,.72,.16);end.castShadow=true;g.add(end);
 // chimney
 box(g,-1.15,3.5,-.6,.48,1.35,.48,stone);
 // door, lintel and window panes
 box(g,.45,.82,1.72,.8,1.55,.16,darkWood);box(g,.45,.78,1.82,.57,1.27,.1,wood);
 sphere(g,.67,.8,1.89,.045,.045,.035,gold,1);
 for(const wx of [-1.2,1.25]){box(g,wx,1.66,1.73,.65,.73,.15,darkWood);box(g,wx,1.66,1.83,.48,.56,.05,mat('glass',0x9caa91));box(g,wx,1.66,1.87,.07,.63,.04,plaster);box(g,wx,1.66,1.87,.5,.07,.04,plaster);box(g,wx,1.25,1.91,.83,.09,.38,wood);}
 // roof beam seams
 for(const xx of [-1.1,1.1]){const beam=box(g,xx,2.9,1.73,.13,1.05,.14,darkWood);beam.rotation.z=xx<0?-.6:.6}
 return g;}
cottage(-11,-9,1.05,plaster,roofLight,.12);cottage(12,-10,.95,plasterRose,roof,-.16);cottage(-13,10,.88,plaster,roof,.42);cottage(13,12,1,plaster,roofLight,-.55);
// Baker's outdoor oven and market stall near the main green
const oven=new THREE.Group();oven.position.set(7.5,-.02,6.6);world.add(oven);cylinder(oven,0,.52,0,1.05,1.12,1.05,stone,10);sphere(oven,0,1.08,0,1.03,.72,.98,stone,1);box(oven,0,.5,.94,.52,.67,.11,darkWood);box(oven,0,.48,1.02,.29,.45,.08,mat('ovenMouth',0x382d24));
const stall=new THREE.Group();stall.position.set(4.5,0,-1.5);world.add(stall);box(stall,0,.9,0,3.2,.14,1.7,wood);for(const x of [-1.4,1.4])for(const z of [-.7,.7])box(stall,x,.55,z,.11,1.1,.11,darkWood);const awning=box(stall,0,1.65,0,3.5,.15,2.0,cloth);awning.rotation.x=-.08;for(let x=-1.25;x<=1.26;x+=.83){const stripe=box(stall,x,1.74,0,.38,.04,2,mat('awningCream',0xe8d6b1));stripe.rotation.x=-.08;}
// Stacked market baskets and bread loaves
for(let i=0;i<3;i++){cylinder(stall,-.85+i*.75,1.1,-.15,.23,.27,.25,mat('basket',0x9b7045),8);sphere(stall,-.85+i*.75,1.28,-.15,.17,.1,.24,mat('bread',0xd5a45e),1)}
// Well, trough, barrels, benches
