const $=s=>document.querySelector(s), modal=$('#modal-backdrop'),toastEl=$('#toast');
let started=false,done=false,coins=0, cameraMode=0, elapsed=0, toastTimer, bannerTimer;
const keys=new Set(), joystick={x:0,y:0,active:false}, playerSpeed=0;
const camTarget=new THREE.Vector3(),camPos=new THREE.Vector3();
function resize(){const w=window.innerWidth,h=window.innerHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<650?61:54;camera.updateProjectionMatrix();}window.addEventListener('resize',resize);resize();
function announce(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function refreshHUD(){const n=herbs.filter(h=>h.userData.taken).length;$('#progress-label').textContent=done?'DELIVERED TO ELSPETH':`${n} / 3 gathered`;$('#progress-fill').style.width=`${Math.min(n/3,1)*100}%`;$('#inventory-count').textContent=`${n} / 6`;
 const inventory=$('#inventory-items');inventory.innerHTML='';for(let i=0;i<6;i++){const slot=document.createElement('div');slot.className='item-slot';if(i<n){slot.innerHTML='✿<small>×1</small>';slot.title='Wild herb'}else slot.textContent='';inventory.appendChild(slot)}
 if(n>=3&&!done){$('#quest-title').textContent='Back to Elspeth';$('#quest-description').textContent='The baker is by her oven. Bring her the herbs you gathered.';$('#location-name').textContent='THE BAKER’S OVEN';$('#progress-label').textContent='RETURN TO ELSPETH';}
}
function nearestTarget(){let best=null,bestDist=3.0;for(const h of herbs){if(h.userData.taken)continue;const d=player.position.distanceTo(h.position);if(d<bestDist){best=h;bestDist=d}}
 const dB=player.position.distanceTo(baker.position);if(dB<3.2&&dB<bestDist){best=baker;bestDist=dB}return best}
function interact(){if(!started)return;const target=nearestTarget();if(!target){announce('Wander the meadow to find wild herbs.');return}
 if(target.userData.kind==='herb'){target.userData.taken=true;target.visible=false;const count=herbs.filter(h=>h.userData.taken).length;announce(count<3?'Wild herb gathered. A lovely find.': 'That’s three! Take them to Elspeth by the oven.');refreshHUD();return}
 if(target===baker){if(herbs.filter(h=>h.userData.taken).length<3){announce('Elspeth: “Could you find me three wild herbs, dear?”');return}if(!done){done=true;coins+=12;refreshHUD();announce('Elspeth: “Just what I needed. Thank you, dear!”');const banner=$('#completion-banner');banner.classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>banner.classList.remove('show'),4800);$('#quest-title').textContent='A good day’s work';$('#quest-description').textContent='The bread is in the oven. Take a moment to enjoy the village.';$('#quest-card .quest-reward').innerHTML='<span class="coin">✦</span> <b>+12</b> village coins <span class="reward-separator">·</span><span class="heart-small">♥</span> <b>+1</b> goodwill';}else announce('Elspeth: “Come back when the oven is warm, dear.”');}}
}
function updateHint(){const target=nearestTarget(), hint=$('#interact-hint'),action=$('#touch-action');if(!started){hint.classList.remove('show');action.style.opacity='.6';return}if(target){hint.classList.add('show');if(target.userData.kind==='herb'){hint.querySelector('.keycap').textContent='E';hint.querySelector('span:nth-child(2)').textContent='Gather wild herb';action.innerHTML='GATHER<br><span>WILD HERB</span>'}else{hint.querySelector('.keycap').textContent='E';hint.querySelector('span:nth-child(2)').textContent=herbs.filter(h=>h.userData.taken).length>=3?'Give herbs to Elspeth':'Talk to the baker';action.innerHTML='TALK<br><span>TO ELSPETH</span>'}action.style.opacity='1'}else{hint.classList.remove('show');action.innerHTML='TAP<br><span>TO GATHER</span>';action.style.opacity='.72'}}
function setStarted(){started=true;modal.classList.add('hidden');$('#fade-overlay').classList.remove('show');announce('A fresh day in Willowmead.');}
$('#start-button').addEventListener('click',setStarted);$('#modal-close').addEventListener('click',setStarted);
$('#help-button').addEventListener('click',()=>{if(started){$('#modal-title').innerHTML='A little guide';$('#modal-copy').textContent='Walk with WASD or the on-screen joystick. Find the shimmering herbs and tap E (or the gather button) nearby. Gather three, then find Elspeth beside the stone oven.';$('#modal-backdrop').classList.remove('hidden')}else modal.classList.remove('hidden')});
$('#sound-button').addEventListener('click',e=>{const on=e.currentTarget.dataset.muted!=='true';e.currentTarget.dataset.muted=String(on);e.currentTarget.textContent=on?'♪':'♫';announce(on?'Ambient sound off':'Ambient sound on');});
$('#camera-button').addEventListener('click',()=>{cameraMode=(cameraMode+1)%3;announce(['Camera: follow','Camera: wide','Camera: close'][cameraMode]);});
$('#touch-action').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='e'||e.key===' '){interact()}if(e.key==='Escape'&&started)$('#modal-backdrop').classList.add('hidden')});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
const joy=$('#joystick'),knob=$('#joystick-knob');let joyPointer=null;
function joyMove(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=29,d=Math.hypot(dx,dy),scale=d>max?max/d:1;joystick.x=dx*scale/max;joystick.y=dy*scale/max;knob.style.transform=`translate(calc(-50% + ${dx*scale}px),calc(-50% + ${dy*scale}px))`;}
joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joystick.active=true;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});function joyEnd(e){if(e.pointerId!==joyPointer)return;joyPointer=null;joystick.active=false;joystick.x=0;joystick.y=0;knob.style.transform='translate(-50%,-50%)'}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);
// Dragging the open sky rotates the follow camera; controls never steal the movement stick.
let drag=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0)drag={x:e.clientX,y:e.clientY};else if(e.pointerType!=='mouse')drag={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x;cameraAngle-=dx*.004;drag={x:e.clientX,y:e.clientY}}});window.addEventListener('pointerup',()=>drag=null);
let cameraAngle=0;
function collides(x,z){ // Keep the walkable village green bounded; cottages and thick trunks feel solid.
 if(Math.abs(x)>25||Math.abs(z)>24)return true;
 const blocks=[[-11,-9,2.7],[12,-10,2.4],[-13,10,2.3],[13,12,2.3]];
 for(const [bx,bz,r] of blocks)if(Math.hypot(x-bx,z-bz)<r)return true;
 return false;
}
const clockEl=$('#clock');
function update(dt){elapsed+=dt;if(started){const mins=8*60+Math.floor(elapsed*1.35),hh=Math.floor(mins/60)%12||12,mm=String(mins%60).padStart(2,'0');clockEl.textContent=`${hh}:${mm} ${mins>=12*60?'PM':'AM'}`;
 let ix=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x;let iz=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y;const len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}if(len>.04){const c=Math.cos(cameraAngle),s=Math.sin(cameraAngle),dx=ix*c+iz*s,dz=-ix*s+iz*c,speed=4.0;const nx=player.position.x+dx*speed*dt,nz=player.position.z+dz*speed*dt;if(!collides(nx,player.position.z))player.position.x=nx;if(!collides(player.position.x,nz))player.position.z=nz;const targetRot=Math.atan2(dx,dz);let diff=((targetRot-player.rotation.y+Math.PI*3)%(Math.PI*2))-Math.PI;player.rotation.y+=diff*Math.min(1,dt*10)}
 for(const h of herbs)if(!h.userData.taken){h.userData.bud.position.y=.57+Math.sin(elapsed*2.7+h.userData.phase)*.055;h.userData.halo.material.opacity=.09+Math.sin(elapsed*2+h.userData.phase)*.035}
 for(const c of clouds)c.position.x+=c.userData.speed*dt;
 updateHint();}
 // Third-person follow and alternate wide/close views.
 const distance=cameraMode===1?10:cameraMode===2?4.6:7.2, height=cameraMode===1?7.2:cameraMode===2?3.5:5.1;
 const yaw=player.rotation.y+cameraAngle, desired=new THREE.Vector3(player.position.x-Math.sin(yaw)*distance,height,player.position.z-Math.cos(yaw)*distance);
 camPos.lerp(desired,1-Math.exp(-dt*3.5));camera.position.copy(camPos);camTarget.set(player.position.x,1.3,player.position.z);camera.lookAt(camTarget);
 // Warm sunlight subtly shifts and canopies sway.
 sun.position.x=-14+Math.sin(elapsed*.025)*3;
}
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;update(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
refreshHUD();

